```

### `inversor.ino`
```cpp
#include "InversorHBridge.h"

const svpm_cfg_t CFG = {
    .freq_hz        = 20000.0f,
    .res_bits       = 10,       // 1024 níveis
    .deadtime_us    = 1.0f,     // 1 µs típico
    .bipolar        = true,
    .delta_y        = true      // sequência Δ-Y para menor dv/dt
};

InversorHBridge inv(CFG, 25, 26, 27, 32, 33, 34);

void setup() {
    Serial.begin(115200);
    inv.start();
    inv.reference(0.0f, 0.0f, 0.0f); // partida com zero
}

void loop() {
    // Simula varredura senoidal de tensão de referência
    float a = sin(microseconds millis()/20000.0f * 2*PI()) * 0.9;
    float b = cos(microseconds millis()/20000.0f * 2*PI()) * 0.9;
    float c = sin(microseconds millis()/20000.0f * 2*PI() + 2*PI()/3.0f) * 0.9;

    inv.reference(a, b, c);
    inv.runSVPWM(); // assume que run() foi exposto

    delay(1);
}
